mapper.update:
update ticket set status='ASSIGNED',
assignee_id=#{assigneeId}
where id=#{ticketId} and status='CREATED'

update ticket set status='PROCESSING'
WHERE id = #{ticketId}
AND assignee_id = #{assigneeId}
AND status = 'ASSIGNED'

update ticket set status='RESOLVED'
WHERE id = #{ticketId}
AND assignee_id = #{assigneeId}
AND status = 'PROCESSING'

update ticket set status='CLOSED'
WHERE id = #{ticketId}
AND creator_id = #{creatorId}
AND status = 'RESOLVED'
